using System.Collections;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using RenoDXMfgUnlocker;

internal static class Rc3GenerationChecks
{
    public static IEnumerable<(string Name,Action Run)> All(){
        yield return("rc3 generation preserves exact method pair and repeated selection state",Mappings);
        yield return("rc3 generation never resets independent saved or pending options",Independent);
        yield return("rc3 generation conflicting pending quality is preserved and Save fails closed",Conflict);
        yield return("rc3 generation XMX warning is contextual to selected or saved XMX",Warnings);
        yield return("rc3 generation saved XMX warning distinguishes pending switch and Discard",Saved);
        yield return("rc3 generation automatic independent sections show only real method keys",Explanations);
        yield return("rc3 generation older and future schemas remain unavailable",Versions);
        yield return("rc3 generation explanation and warnings localize across six languages",Localization);
    }
    private const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
    private static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,Flags)!.Invoke(o,args);
    private static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
    private static StackPanel Panel(Rc1SettingsChecks.Fixture f)=>(StackPanel)f.Window.FindName("GenerationModePanel");
    private static GenerationMethodPresentation Info(Rc1SettingsChecks.Fixture f)=>(GenerationMethodPresentation)((Border)Panel(f).Children[1]).Tag;
    private static TextBlock Warning(Rc1SettingsChecks.Fixture f)=>(TextBlock)Panel(f).Children[2];
    private static void Select(Rc1SettingsChecks.Fixture f,string mode)=>Call(f.Window,"SelectGenerationMethod",mode);
    private static IEnumerable<DependencyObject> Tree(DependencyObject root){foreach(var c in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>()){yield return c;foreach(var n in Tree(c))yield return n;}}
    private static string[] Texts(Rc1SettingsChecks.Fixture f)=>Tree((Border)Panel(f).Children[1]).OfType<TextBlock>().Select(t=>t.Text).ToArray();
    private static void Mappings()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();foreach(var (mode,backend,xmx) in new[]{("DLSSG","DLSSG","0"),("XeMFG","XeMFG","0"),("XMX","DLSSG","1")}){Select(f,mode);Check(f.Value("Selected")==backend&&f.Value("XmxGenerator")==xmx,"INI mapping changed");var info=Info(f);Select(f,mode);Check(Info(f)==info&&info.IniValues.Contains("[Backend] Selected: DLSSG → "+backend)&&info.IniValues.Contains("[DLSSG] XmxGenerator: 0 → "+xmx),"Repeated selection or technical values changed");}});
    private static MfgUnlockSettingDefinition Definition(object row)=>(MfgUnlockSettingDefinition)row.GetType().GetProperty("Definition")!.GetValue(row)!;
    private static void Independent()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();var hashes=f.Hashes();var independent=f.Rows.Select(Definition).Where(d=>!MfgSettingsLayout.IsMethodKey(d.Key)).ToArray();foreach(var d in independent)f.Edit(d.Key,d.Choices.First(c=>c.Value!=d.DefaultValue).Value);var values=independent.ToDictionary(d=>d.Key,d=>f.Value(d.Key));foreach(var mode in new[]{"XMX","XeMFG","DLSSG","XMX","DLSSG"}){Select(f,mode);foreach(var category in Enum.GetValues<MfgSettingsCategory>()){f.Select(category);Check(values.All(v=>f.Value(v.Key)==v.Value),"Method/category silently reset "+mode);}}Check(hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Method selection wrote to disk");});
    private static void Conflict()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();var hashes=f.Hashes();f.Edit("TemporalFix","0");Select(f,"XMX");Check(f.Value("TemporalFix")=="0"&&!(bool)f.Row("TemporalFix").GetType().GetProperty("CanEdit")!.GetValue(f.Row("TemporalFix"))!,"Pending value lost or lockout removed");Check(!((Button)f.Window.FindName("MfgSettingsSaveButton")).IsEnabled&&((Button)f.Window.FindName("MfgSettingsDiscardButton")).IsEnabled,"Conflicting Save enabled or Discard blocked");Call(f.Window,"MfgSettingsSave_Click",f.Window,new RoutedEventArgs());Check(f.Window.OwnedWindows.Count==0&&hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Direct blocked Save opened confirmation or wrote files");Select(f,"DLSSG");Check(f.Value("TemporalFix")=="0"&&((Button)f.Window.FindName("MfgSettingsSaveButton")).IsEnabled,"Returning to NVIDIA lost pending edit");((Button)f.Window.FindName("MfgSettingsDiscardButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(f.Value("TemporalFix")=="1"&&f.Edits().Length==0,"Shared Discard failed");});
    private static void Warnings()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();foreach(var mode in new[]{"DLSSG","XeMFG","XMX","DLSSG"}){Select(f,mode);Check(Warning(f).Visibility==(mode=="XMX"?Visibility.Visible:Visibility.Collapsed),"Unrelated XMX warning leaked to "+mode);Check(Info(f).SelectedXmx==(mode=="XMX")&&!Info(f).SavedXmx,"Selected/saved distinction lost");if(mode=="XeMFG")Check(Info(f).Description.Contains("pinned XeSS-FG / XeLL")&&!Info(f).Description.Contains("XMX"),"Intel requirements wrong");if(mode=="DLSSG")Check(Info(f).Description.Contains("supported existing DLSS")&&!Info(f).Description.Contains("XMX"),"NVIDIA requirements wrong");}});
    private static void Saved()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();var path=Path.Combine(f.Root,"MFGAdaUnlock.ini");File.WriteAllText(path,"[Backend]\nSelected=DLSSG\n[DLSSG]\nXmxGenerator=1\n");var service=new MfgUnlockSettingsService(true);var snapshot=service.Load(path,f.Root,"1.8.0.0");var docs=(IList)typeof(MainWindow).GetField("mfgSettingsDocuments",Flags)!.GetValue(f.Window)!;var old=docs[1]!;old.GetType().GetProperty("Snapshot")!.SetValue(old,snapshot);var hashes=f.Hashes();Call(f.Window,"UpdateMfgSettingsButtons");Check(Info(f).SavedXmx&&!Info(f).SelectedXmx&&Info(f).Pending&&Info(f).ContextWarning==GenerationMethodPresentation.SavedXmxWarning,"Saved XMX not distinguished from proposed NVIDIA");Select(f,"XeMFG");Check(Info(f).ContextWarning==GenerationMethodPresentation.SavedXmxWarning,"Saved warning lost on Intel pending switch");((Button)f.Window.FindName("MfgSettingsDiscardButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(Info(f).SelectedXmx&&Info(f).SavedXmx&&!Info(f).Pending&&Info(f).ContextWarning==GenerationMethodPresentation.SelectedXmxWarning,"Discard did not restore saved XMX context");Check(hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Saved-state presentation wrote config");});
    private static void Explanations()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();var l=LocalizedPresentation.Language;var text=Texts(f);foreach(var key in new[]{"Automatically configured by method selection","Additional settings — configured independently","Other generator-related settings are available under Advanced and Other."})Check(text.Contains(l.Lookup(key)),"Missing explanation "+key);var technical=text.Single(t=>t.StartsWith("MFGAdaUnlock.ini\n"));Check(technical.Split('\n').Length==3&&technical.Contains("[Backend] Selected:")&&technical.Contains("[DLSSG] XmxGenerator:"),"Automatic section claims unrelated keys");Check(text.Any(t=>t.Contains("HUD")&&t.Contains("Vulkan")&&t.Contains("2x")),"Independent options unexplained");Check(Panel(f).Children.Count==3&&Tree((FrameworkElement)f.Window.FindName("MfgSettingsFooter")).OfType<Button>().Count()==3,"Extra Save workflow created");});
    private static void Versions()=>WpfCheckHost.Run(()=>{foreach(var v in new[]{"1.6.0.0","1.7.0.0","1.8.0-beta.1","Unknown"}){using var f=new Rc1SettingsChecks.Fixture(v);Select(f,"XMX");Check(Panel(f).Visibility==Visibility.Collapsed&&Panel(f).Children.Count==0,"Unreviewed XMX explanation/selector exposed for "+v);}});
    private static void Localization()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();Select(f,"XMX");var language=LocalizedPresentation.Language;var keys=new[]{"Automatically configured by method selection","Additional settings — configured independently","The method buttons change only these generation preferences (saved → proposed):","HUD stabilization, Vulkan options, NVIDIA quality, Intel stock 2x model and borderless presentation remain independent in General / Advanced / Other. Method selection does not enable or disable their values.","Not every option applies to every generator. Existing capability lockouts still apply. Most experimental options can stay at existing/default values unless troubleshooting a specific issue.","Other generator-related settings are available under Advanced and Other.",GenerationMethodPresentation.SelectedXmxWarning,GenerationMethodPresentation.SavedXmxWarning};try{Check(language.ValidateCatalogs().Count==0,"Resource integrity");foreach(var c in UiLocalization.Cultures){language.SetCulture(c,false);foreach(var key in keys)Check(language.GetCatalog(c).ContainsKey(key)&&(c=="en-US"||language.Lookup(key)!=key),"Untranslated "+c+" / "+key);Check(Warning(f).Text==language.Lookup(GenerationMethodPresentation.SelectedXmxWarning),"Late warning untranslated");Check(Texts(f).Contains(language.Lookup(keys[0]))&&Texts(f).Contains(language.Lookup(keys[1])),"Late headings untranslated");Check(Info(f).IniValues.Contains("[DLSSG] XmxGenerator: 0 → 1")&&f.Value("XmxGenerator")=="1"&&TechnicalVersionDisplay.Format("1,8,0,0")=="1.8.0.0","Culture changed technical state");}}finally{language.SetCulture("en-US",false);}});
}
